body.script:
self.__next_f.push([1,"(function () {
 var path = location.pathname

 function go(url) {
 var from = path.replace(/\/$/, '') || '/'
 var to = url.replace(/\/$/, '') || '/'
 if (from === to) { return }
 document.documentElement.style.visibility = 'hidden'
 location.replace(url + location.search + location.hash)
 }
 function bare(p) {
 var rest = p.replace(/\/$/, '') || '/'
 return rest === '/zh' ? '/' : rest.indexOf('/zh/') === 0 ? rest.slice(3) : rest
 }
 function slash(p) {
 return p === '/' || p.slice(-5) === '.html' ? p : p + '/'
 }
 function is404Path(p) {
 var rest = p.replace(/\/$/, '') || '/'
 return rest === '/404' || rest === '/en/404'
 }
 function preferEn() {
 var cookie = document.cookie.match(/(?:^|;\s*)NEXT_LOCALE=(zh|en)(?:;|$)/)
 var tag = String(navigator.language || (navigator.languages && navigator.languages[0]) || '')
 .toLowerCase().replace(/_/g, '-')
 return cookie ? cookie[1] === 'en' : !(/^zh\b/.test(tag) && !/hant|tw|hk|mo/.test(tag))
 }

 if (path === '/zh' || path.indexOf('/zh/') === 0) {
 document.cookie = 'NEXT_LOCALE=zh; path=/'
 }
 if (path === '/zh' || path === '/zh/') {
 go('/')
 return
 }

 // oss fallback 到 index，index 需要再判断自己应该不应该 404

 if (document.querySelector('meta[name="app-home"]') && path !== '/' && !is404Path(path)) {
 var en = path === '/en' || path.indexOf('/en/') === 0 || preferEn()
 go(en ? '/en/404/' : '/404/')
 return
 }

 if (path === '/en' || path.indexOf('/en/') === 0) { return }

 if (path.indexOf('/zh/') === 0) {
 go(slash(bare(path)))
 return
 }

 if (!preferEn()) { return }

 if (document.querySelector('meta[name="app-not-found"]')) {
 go('/en/404/')
 return
 }
 var rest = path.replace(/\/$/, '') || '/'
 go(rest === '/' ? '/en/' : '/en' + slash(rest))
})();"])
